const colors={'Capital area':'#4b7653',Gangwon:'#bac797',Chungcheong:'#c6b873',Gyeongsang:'#94a47b',Jeolla:'#d0d7a9',Jeju:'#779b8a'};
let year=2024,selected=0,mode='population',timer=null,imported=null;const $=s=>document.querySelector(s);const fmt=n=>n.toLocaleString('en-US');const million=n=>(n/1e6).toFixed(2)+'M';const pct=n=>(n>=0?'+':'')+n.toFixed(1)+'%';
function pop(r,y){if(imported)return imported[y][r.name];if(r.name==='Sejong'&&y<2012)return 0;const years=[2000,2010,2020,2024];let a=Math.min(2,years.findIndex((v,i)=>y>=v&&y<=years[i+1]));if(a<0)a=2;return Math.round(r.anchors[a]+(r.anchors[a+1]-r.anchors[a])*(y-years[a])/(years[a+1]-years[a]));}
function growth(r){const b=pop(r,+$('#year').min);return b?(pop(r,year)/b-1)*100:null}
function stop(){clearInterval(timer);timer=null;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Play timeline')}
function render(){const base=+$('#year').min,total=regions.reduce((s,r)=>s+pop(r,year),0),old=regions.reduce((s,r)=>s+pop(r,base),0);$('#yearLabel').textContent=year;$('#statYear').textContent=year;$('#total').textContent=million(total);$('#nationalChange').textContent=pct((total/old-1)*100);$('.summary-bottom span:last-child').textContent='since '+base;$('#change').textContent='Change since '+base;$('.focus-change>span').textContent='Change since '+base;$('#map').innerHTML=regions.map(r=>{const n=Math.round(pop(r,year)/1e5),cols=Math.ceil(Math.sqrt(n)),rows=Math.ceil(n/cols),size=9,g=growth(r),color=mode==='population'?colors[r.group]:g===null?'#bec3af':g>10?'#47795e':g>=0?'#9cba8d':g> -10?'#ceb986':'#bc8d70';let tiles='';for(let i=0;i<n;i++)tiles+=`<rect class="tile" x="${r.x+(i%cols-cols/2)*size}" y="${r.y+(Math.floor(i/cols)-rows/2)*size}" width="8.6" height="8.6" rx=".7" fill="${color}"/>`;return `<g tabindex="0" role="button" aria-label="${r.name}, ${fmt(pop(r,year))} people" data-region="${r.id}" class="region ${r.id===selected?'selected':''}"><title>${r.name}: ${fmt(pop(r,year))}</title>${tiles}${n?`<text class="map-label" x="${r.x}" y="${r.y+rows*size/2+14}" text-anchor="middle">${r.name}</text>`:''}</g>`}).join('');$('#legend').innerHTML=mode==='population'?Object.entries(colors).map(([n,c])=>`<span><i style="background:${c}"></i>${n}</span>`).join(''):[['#bc8d70','< −10%'],['#ceb986','−10 to 0%'],['#9cba8d','0 to +10%'],['#47795e','> +10%'],['#bec3af','No baseline']].map(([c,n])=>`<span><i style="background:${c}"></i>${n.replace('<','&lt;')}</span>`).join('');const r=regions[selected],g=growth(r);$('#regionName').textContent=r.name;$('#regionKr').textContent=r.kr;$('#regionPop').textContent=fmt(pop(r,year));$('#share').textContent=(pop(r,year)/total*100).toFixed(1)+'%';$('#regionChange').textContent=g===null?'New region':pct(g);const end=+$('#year').max,ys=Array.from({length:end-base+1},(_,i)=>base+i),values=ys.map(y=>pop(r,y)),lo=Math.min(...values)*.98,hi=Math.max(...values)*1.02,points=values.map((v,i)=>[i/(values.length-1)*280,65-(v-lo)/(hi-lo||1)*55]);const path=points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');const point=points[year-base];$('#spark').innerHTML=`<path d="${path} L280,75 L0,75 Z" fill="#edf1e3"/><path d="${path}" fill="none" stroke="#92a670" stroke-width="2"/><circle cx="${point[0]}" cy="${point[1]}" r="3.5" fill="#426d4c"/>`;$('.spark-labels').innerHTML=`<span>${base}</span><span>${end}</span>`;const ranked=[...regions].sort((a,b)=>pop(b,year)-pop(a,year));$('#ranking').innerHTML=ranked.slice(0,4).map((r,i)=>`<button class="rank-row" data-region="${r.id}"><span class="rank-num">0${i+1}</span><span><span class="rank-name">${r.name}</span><span class="rank-bar"><i style="width:${pop(r,year)/pop(ranked[0],year)*100}%"></i></span></span><span class="rank-value">${million(pop(r,year))}</span></button>`).join('')}
document.addEventListener('click',e=>{const region=e.target.closest('[data-region]');if(region){selected=+region.dataset.region;render()}});$('#map').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.region){e.preventDefault();selected=+e.target.dataset.region;render()}});$('#map').addEventListener('pointermove',e=>{const g=e.target.closest('[data-region]');if(!g){$('#tooltip').style.display='none';return}const r=regions[+g.dataset.region];$('#tooltip').textContent=`${r.name} · ${million(pop(r,year))} people`;Object.assign($('#tooltip').style,{display:'block',left:Math.min(e.clientX+15,innerWidth-210)+'px',top:e.clientY+18+'px'})});$('#map').addEventListener('pointerleave',()=>$('#tooltip').style.display='none');$('#year').addEventListener('input',e=>{stop();year=+e.target.value;render()});$('#play').onclick=()=>{if(timer)return stop();if(year===+$('#year').max)year=+$('#year').min;render();$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Pause timeline');timer=setInterval(()=>{if(year>=+$('#year').max)return stop();year++;$('#year').value=year;render()},650)};['population','change'].forEach(id=>$('#'+id).onclick=()=>{mode=id;$('.segmented .active').classList.remove('active');$('#'+id).classList.add('active');render()});$('#about').onclick=()=>$('#dataDialog').showModal();$('#closeDialog').onclick=()=>$('#dataDialog').close();$('#import').onclick=()=>{$('#dataDialog').showModal()};$('#chooseFile').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const text=await e.target.files[0].text(),lines=text.trim().split(/\r?\n/),head=lines.shift().replace(/^\uFEFF/,'').toLowerCase().split(',').map(x=>x.trim());if(head.join(',')!=='year,region,population')throw Error('Use the header year,region,population.');const data={};for(const line of lines){if(!line.trim())continue;const [y,name,p]=line.split(',').map(x=>x.trim());if(!/^\d{4}$/.test(y)||!regions.some(r=>r.name===name)||!Number.isFinite(+p)||+p<0||!p)throw Error('Invalid row: '+line);data[y]??={};if(name in data[y])throw Error('Duplicate region in '+y);data[y][name]=Math.round(+p)}const years=Object.keys(data).map(Number).sort((a,b)=>a-b);if(years.length<2)throw Error('Include at least two consecutive years.');if(years.at(-1)-years[0]+1!==years.length)throw Error('Include every year in the range.');if(years.some(y=>Object.keys(data[y]).length!==17||Object.values(data[y]).reduce((a,b)=>a+b,0)===0))throw Error('Include all 17 regions and a positive total for each year.');stop();imported=data;$('#year').min=years[0];$('#year').max=years.at(-1);year=years.at(-1);$('#year').value=year;$('.ticks').innerHTML=years.filter((_,i)=>i===0||i===years.length-1||i%Math.ceil(years.length/5)===0).map(y=>`<span>${y}</span>`).join('');$('.intro-note span').textContent=`IMPORTED DATA · ${years[0]}–${year}`;$('#dataStatus').textContent='Using your imported dataset.';$('#importStatus').textContent='Imported '+years.length+' years successfully. Figures have not been independently verified.';render();}catch(err){$('#importStatus').textContent=err.message}e.target.value=''};$('#download').onclick=()=>{let csv='year,region,population\n';for(let y=+$('#year').min;y<=+$('#year').max;y++)for(const r of regions)csv+=`${y},${r.name},${pop(r,y)}\n`;const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download=imported?'korea-population-imported.csv':'korea-population-ILLUSTRATIVE.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();
